const rd=f=>{if(!fs.existsSync(f)) throw new Error("missing "+f); const r=fs.readFileSync(f,"utf8").trim(); const v=Number(r); if(!Number.isFinite(v)) throw new Error("non-numeric "+f+": "+r); return v;};
const seed=rd("seed.txt"), s1=rd("stage1.txt"), s2=rd("stage2.txt"), s3=rd("stage3.txt");
const exp1=seed+2, exp2=exp1*exp1, exp3=exp2-4;
console.log("seed="+seed, "expected:", exp1, exp2, exp3, "| files:", s1, s2, s3);
const rel=[["stage1==seed+2", s1===exp1],["stage2==stage1^2", s2===s1*s1],["stage3==stage2-4", s3===s2-4]];
rel.forEach(([n,ok])=>console.log(ok?"PASS":"FAIL",n));
const a=JSON.parse(fs.readFileSync("answer.json","utf8"));
const keys=Object.keys(a).sort();
const typesOk=keys.every(k=>typeof a[k]==="number");
const valsOk=a.stage1===s1&&a.stage2===s2&&a.stage3===s3;
const keysOk=JSON.stringify(keys)===JSON.stringify(["stage1","stage2","stage3"]);
console.log("answer.json:",JSON.stringify(a));
console.log("keysOk:",keysOk,"typesOk:",typesOk,"valuesMatchFiles:",valsOk);
if(!rel.every(([,o])=>o)||!keysOk||!typesOk||!valsOk) {console.log("OVERALL FAIL"); process.exit(1);}
console.log("OVERALL PASS");
'

